/**
 * Las imágenes del pase de Apple Wallet, incrustadas.
 *
 * Apple exige `icon.png` (y agradece `logo.png`) dentro del `.pkpass`, y las
 * quiere en 1x, 2x y 3x. Antes venían por variables de entorno en base64, lo
 * que obligaba a cargar seis blobs en Vercel a mano y a que nadie supiera de
 * dónde salían. Acá están generadas desde los archivos de marca del repo
 * (`public/img/habi-next-logo.svg` y el asterisco de `Asterisk.tsx`, en
 * violeta sobre el fondo del pase) y optimizadas a paleta. La franja
 * (`strip.png`, la que va debajo de la cabecera en la tarjeta) se compuso con
 * ImageMagick a partir de la Bogotá del carnet, la trama de puntos y los dos
 * asteriscos, y pesa unos 240 KB entre sus tres tamaños: es lo que más pesa
 * del bundle del servidor y aun así cabe sin pensarlo.
 *
 * Para regenerarlas: rsvg-convert a cada tamaño, PIL `quantize` + `optimize`
 * y base64. No se editan a mano.
 */
export const RECURSOS_PASE: Record<string, string> = {
  /** 29×29 */
  "icon.png":
    "",
  /** 58×58 */
  "icon@2x.png":
    "",
  /** 87×87 */
  "icon@3x.png":
    "",
  /** 160×50 */
  "logo.png":
    "",
  /** 320×100 */
  "logo@2x.png":
    "",
  /** 480×150 */
  "logo@3x.png":
    "",
  /** 375×98 franja de marca: la noche, Bogotá y los dos asteriscos; el nombre va encima, a la izquierda */
  "strip.png":
    "",
  /** 750×196 franja de marca: la noche, Bogotá y los dos asteriscos; el nombre va encima, a la izquierda */
  "strip@2x.png":
    "",
  /** 1125×294 franja de marca: la noche, Bogotá y los dos asteriscos; el nombre va encima, a la izquierda */
  "strip@3x.png":
    "",
};
